fn remove_duplicates(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }

    let mut distinct_count = 1; // Start with 1 because the first element is always unique
    let mut previous = nums[0];

    for &num in &nums[1..] {
        if num != previous {
            distinct_count += 1;
            previous = num;
        }
    }

    distinct_count
}